        let itemsRestored = 0;
        let itemsUnchanged = 0;
        let itemsSkippedByOwner = 0;
        let itemsExcluded = 0;
        let itemsMetadataOnly = 0;
        let itemsSkippedTombstoned = 0;
        let itemsSkippedStaleClaim = 0;
        let chunksAwaitingEmbedding = 0;
