  "chunk",
  "chunks",
  "content",
  "document",
  "html",
  "markdown",
  "message",
  "messages",
  "packet",
  "passage",
  "raw",
  "rawpacket",
  "rawsource",
  "rawtext",
  "snippet",
  "sourcepacket",
